#include <stdio.h>
#include <stdlib.h>

#define MAX_ITEMS 5

int stock[MAX_ITEMS];
int price[MAX_ITEMS];

void sell(int sku, int qty) {
    if (stock[sku] < qty) {
        printf("INSUFFICIENT_STOCK sku=%d\n", sku);
        return;
    }
    stock[sku] -= qty;
    int revenue = price[sku] * qty;
    printf("SELL sku=%d qty=%d revenue+=%d\n", sku, qty, revenue);
}

void restock(int sku, int qty) {
    stock[sku] += qty;
    printf("RESTOCK sku=%d qty=%d\n", sku, qty);
}

void report() {
    printf("FINAL stock=");
    for (int i = 0; i < MAX_ITEMS; i++) {
        printf("%d", stock[i]);
        if (i < MAX_ITEMS - 1) {
            printf(",");
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    // Initialize stock and price arrays
    for (int i = 0; i < MAX_ITEMS; i++) {
        stock[i] = 0;
        price[i] = 10; // default price
    }

    int revenue = 0;
    for (int i = 1; i < argc; i += 3) {
        char *op = argv[i];
        int sku = atoi(argv[i + 1]);
        int qty = atoi(argv[i + 2]);

        if (strcmp(op, "S") == 0) {
            sell(sku, qty);
            revenue += price[sku] * qty;
        } else if (strcmp(op, "R") == 0) {
            restock(sku, qty);
        } else {
            printf("INVALID_OP\n");
        }
    }

    report();
    printf(" revenue=%d\n", revenue);
    return 0;
}
